    drop(session.initialize());
    let start_ms = start.elapsed().as_secs_f64() * 1000.0;

    let keys_start = Instant::now();
    let keys = session.component_keys();
    let keys_ms = keys_start.elapsed().as_secs_f64() * 1000.0;

