#![allow(clippy::unwrap_used, clippy::expect_used, clippy::print_stdout)]
//! Scratch benchmark for trail 166 (never committed).
//!
//!   zz_watch_bench --src DIR --scenario edit|component|serialize|publish [--dependencies] [--full] [--edits N]
//!
//! Prints one JSON line with the per-iteration milliseconds.
use std::time::Instant;

use caliper_docgen_core::pipeline::{HtmlAttributeMode, PipelineOptions, WatchSession};
use camino::{Utf8Path, Utf8PathBuf};

fn arg(args: &[String], name: &str) -> Option<String> {
    args.iter().position(|a| a == name).and_then(|at| args.get(at + 1)).cloned()
}

fn ms(start: Instant) -> f64 {
    start.elapsed().as_secs_f64() * 1000.0
}

fn leaf_files(src: &Utf8Path) -> Vec<Utf8PathBuf> {
    let mut found = Vec::new();
    let mut stack = vec![src.to_path_buf()];
    while let Some(dir) = stack.pop() {
        for entry in std::fs::read_dir(&dir).unwrap().flatten() {
            let path = Utf8PathBuf::from_path_buf(entry.path()).unwrap();
            if path.is_dir() {
                if path.file_name() != Some("node_modules") {
                    stack.push(path);
                }
            } else if path.extension() == Some("tsx") && !path.as_str().contains(".stories.") {
                let text = std::fs::read_to_string(&path).unwrap_or_default();
                if text.contains("export const") && text.len() > 800 {
                    found.push(path);
                }
            }
        }
    }
    found.sort();
    found
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let flag = |name: &str| args.iter().any(|a| a == name);
    let src = Utf8PathBuf::from(arg(&args, "--src").expect("--src"));
    let scenario = arg(&args, "--scenario").expect("--scenario");
    let edits: usize = arg(&args, "--edits").map_or(24, |n| n.parse().unwrap());
    let options = PipelineOptions {
        src_dirs: vec![src.clone()],
        load_dependencies: flag("--dependencies"),
        html_attributes: if flag("--full") { HtmlAttributeMode::Full } else { HtmlAttributeMode::Curated },
        ..Default::default()
    };
    let session = WatchSession::new(options);
    let start = Instant::now();
    drop(session.initialize());
    let init_ms = ms(start);

    let mut times = Vec::new();
    match scenario.as_str() {
        "edit" => {
            let files = leaf_files(&src);
            let picked: Vec<Utf8PathBuf> = [files.len() / 5, files.len() / 2, files.len() * 4 / 5]
                .iter()
                .map(|&i| files[i].clone())
                .collect();
            let originals: Vec<String> = picked.iter().map(|p| std::fs::read_to_string(p).unwrap()).collect();
            for n in 0..edits {
                let at = n % picked.len();
                std::fs::write(&picked[at], format!("{}\n// edit {n}\n", originals[at])).unwrap();
                let t = Instant::now();
                let update = session.update_file(&picked[at]);
                times.push(ms(t));
                std::hint::black_box(update);
            }
            for (path, text) in picked.iter().zip(&originals) {
                std::fs::write(path, text).unwrap();
            }
        }
        "component" => {
            let keys = session.component_keys();
            let t = Instant::now();
            for key in keys.iter().take(100) {
                std::hint::black_box(session.component(key));
            }
            times.push(ms(t));
        }
        "serialize" => {
            let output = session.current_output().unwrap();
            for _ in 0..edits {
                let t = Instant::now();
                let bytes = serde_json::to_vec(&*output).unwrap();
                times.push(ms(t));
                std::hint::black_box(bytes);
            }
        }
        "publish" => {
            for _ in 0..edits {
                let t = Instant::now();
                let snapshot = session.snapshot();
                times.push(ms(t));
                std::hint::black_box(snapshot);
            }
            let mut shared = Vec::new();
            for _ in 0..edits {
                let t = Instant::now();
                let out = session.current_output();
                shared.push(ms(t));
                std::hint::black_box(out);
            }
            println!("{{\"initMs\":{init_ms:.1},\"snapshotMs\":{times:.2?},\"currentOutputMs\":{shared:.3?}}}");
            return;
        }
        other => panic!("unknown scenario {other}"),
    }
    println!("{{\"initMs\":{init_ms:.1},\"ms\":{times:.2?}}}");
}

