#!/bin/bash
# usage: run.sh BIN CORPUS(antd|shadcn) [scenario...]
BIN=/tmp/claude-501/t166/$1
case "$2" in
  antd) SRC=/tmp/claude-501/t166/ant-design/components ;;
  shadcn) SRC=/tmp/claude-501/t166/shadcn-ui/apps/v4 ;;
esac
shift 2
SCEN="${@:-edit publish component serialize}"
echo "== $BIN $SRC load: $(uptime | sed 's/.*load averages: //')"
for s in $SCEN; do
  case $s in
    edit) N=24 ;;
    serialize) N=9 ;;
    publish) N=10 ;;
    *) N=1 ;;
  esac
  $BIN --src $SRC --scenario $s --dependencies --full --edits $N | python3 -c '
import sys, json, statistics as st
d = json.load(sys.stdin)
s = "'$s'"
if s == "edit":
    m = d["ms"][1:]
    print("edit: init", d["initMs"], "median", round(st.median(m), 2), "min", min(m), "max", max(m))
elif s == "publish":
    print("publish: snapshot median", round(st.median(d["snapshotMs"]), 3), "currentOutput max", max(d["currentOutputMs"]))
elif s == "component":
    print("component: 100 calls ms", d["ms"][0])
else:
    m = d["ms"]
    print("serialize: median", round(st.median(m), 2), "min", min(m), "max", max(m))
'
done

